import { z } from "zod";
import { singleLine } from "./text";

/** An identifier in the canonical 8-4-4-4-12 hex form (any UUID version, as generated by the database). */
export const uuid = () =>
  z
    .string({ error: "Enter a valid ID." })
    .regex(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i, "Enter a valid ID.")
    .transform((v) => v.toLowerCase());

/** `YYYY-MM-DD`, and a real calendar day (2026-02-30 is refused). Stays a string: no time zone is implied. */
export const isoDate = () =>
  z
    .string({ error: "Enter a date as YYYY-MM-DD." })
    .regex(/^\d{4}-\d{2}-\d{2}$/, "Enter a date as YYYY-MM-DD.")
    .refine((v) => {
      const [y, m, d] = v.split("-").map(Number);
      const date = new Date(Date.UTC(y, m - 1, d));
      return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
    }, "Enter a date that exists.");

/** Largest money amount accepted anywhere: 1,000,000,000.00 in cents. Well inside Number.MAX_SAFE_INTEGER. */
export const MAX_CENTS = 100_000_000_000;

/** Whole, non-negative integer cents with an upper bound. Floats and strings are refused, never rounded. */
export const cents = (max: number = MAX_CENTS) =>
  z
    .number({ error: "Enter an amount in whole cents." })
    .int("Enter an amount in whole cents.")
    .min(0, "Enter an amount of 0 or more.")
    .max(max, "That amount is too large.");

/** Trimmed, lowercased, length-limited email address (254 is the SMTP path limit). */
export const email = () =>
  singleLine(254)
    .pipe(z.email({ error: "Enter a valid email address." }))
    .transform((v) => v.toLowerCase());

const MAX_URL_LENGTH = 2048;

/** A URL restricted to the given schemes (default http/https), without embedded credentials. Returned as typed. */
export const url = (schemes: readonly string[] = ["http", "https"]) =>
  singleLine(MAX_URL_LENGTH).refine(
    (value) => {
      if (/\s/u.test(value)) return false;
      try {
        const parsed = new URL(value);
        return (
          schemes.includes(parsed.protocol.replace(/:$/, "").toLowerCase()) &&
          parsed.username === "" &&
          parsed.password === "" &&
          parsed.hostname !== ""
        );
      } catch {
        return false;
      }
    },
    `Enter a valid URL starting with ${schemes.map((s) => `${s}://`).join(" or ")}.`,
  );

export const MAX_TAGS = 10;
export const MAX_TAG_LENGTH = 30;

/** 0 to 10 tags of 1 to 30 characters; duplicates (ignoring case) collapse to the first spelling. */
export const tags = () =>
  z
    .array(singleLine(MAX_TAG_LENGTH), { error: "Enter tags as a list." })
    .max(MAX_TAGS, `Use ${MAX_TAGS} tags or fewer.`)
    .transform((list) => {
      const seen = new Set<string>();
      return list.filter((tag) => {
        const key = tag.toLocaleLowerCase("en-US");
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      });
    });

/** An enum with a plain-language message that lists the allowed values. */
export const choice = <const T extends readonly [string, ...string[]]>(values: T) =>
  z.enum(values, { error: `Choose one of: ${values.join(", ")}.` });
